package com.petlis.service.impl;
import com.petlis.common.exception.BusinessException;import com.petlis.common.security.AccessService;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.PlatformTransactionManager;import java.nio.charset.StandardCharsets;import java.util.*;
/** Finance adapter for the shared durable outbox; never schedules or automatically sends. */
@Service public class LegacyFinanceMailService extends LegacyBusinessMailService {
 private final LegacyMonthlyReportService monthly;private final LegacyHtmlPdfRenderer pdf;private final LegacyFinanceMailFiles artifacts;
 public LegacyFinanceMailService(FeatureStore store,AccessService access,LegacyOrderDetailService renderer,LegacyMailTransport transport,PlatformTransactionManager manager,@Value("${app.legacy-mail.profile-id:1}")int profile,@Value("${app.legacy-mail.override-to:}")String override,@Value("${app.jwt.secret}")String secret,LegacyMonthlyReportService monthly,LegacyHtmlPdfRenderer pdf,LegacyFinanceMailFiles artifacts){super(store,access,renderer,transport,manager,profile,override,secret,Kind.FINANCE_MAIL,null);this.monthly=monthly;this.pdf=pdf;this.artifacts=artifacts;}
 public record Period(String month,String from,String to){}
 public record FinanceCommand(Period period,long contactId,String title,String html,String reportHtml,String pdfTitle,String requestKey,String expectedToken){}
 private Map<String,Object> periodDraft(long hospital,Period p){if(p==null)throw new BusinessException(400,"账单期间缺失");if(p.month()!=null&&!p.month().isEmpty()){if(p.from()!=null||p.to()!=null)throw new BusinessException(400,"账单月份和收样期间不能同时填写");return monthly.draft(hospital,p.month(),null,null);}return monthly.rangeDraft(hospital,p.from(),p.to(),null,null);}
 private List<Map<String,Object>> financeContacts(long hospital){return store.jdbc().queryForList("SELECT InfoHospitalContactId,Name,Mail FROM lin_lb_infohospitalcontact WHERE InfoHospitalId=? ORDER BY InfoHospitalContactId",hospital);}
 private String version(long hospital,Period period){var bill=periodDraft(hospital,period);var hosp=store.one("SELECT InfoHospitalId,HospitalName,PayType FROM lin_lb_infohospital WHERE InfoHospitalId=?",hospital);return fingerprint(Map.of("hospital",new TreeMap<>(hosp),"period",period,"items",bill.get("items"),"contacts",financeContacts(hospital)));}
 public Map<String,Object> compose(long hospital,Period period){read();var result=new LinkedHashMap<>(periodDraft(hospital,period));result.put("contacts",financeContacts(hospital));result.put("editToken",version(hospital,period));return result;}
 private Long replay(int actor,String key,String hash){var rows=store.jdbc().queryForList("SELECT id,business_type,request_fingerprint FROM lin_mail_message WHERE requested_by=? AND request_key=?",actor,key);if(rows.isEmpty())return null;var row=rows.get(0);if(!"FINANCE_MAIL".equals(row.get("business_type"))||!hash.equals(row.get("request_fingerprint")))throw new BusinessException(409,"请求号已用于其他邮件");return ((Number)row.get("id")).longValue();}
 public long queueFinance(long hospital,FinanceCommand c){
  if(!policy(false)[1])throw new BusinessException(409,"财务邮件创建尚未开启");
  if(c==null||c.contactId()<1||c.title()==null||c.title().length()>2000||c.title().chars().anyMatch(n->n==0||n==10||n==13)||c.html()==null||c.reportHtml()==null||c.html().getBytes(StandardCharsets.UTF_8).length>2*1024*1024||c.reportHtml().getBytes(StandardCharsets.UTF_8).length>2*1024*1024||c.requestKey()==null||!c.requestKey().matches("[A-Za-z0-9_-]{16,64}")||c.expectedToken()==null||!c.expectedToken().matches("[a-f0-9]{64}"))throw new BusinessException(400,"财务邮件参数无效，请重新打开账单");
  LegacyFinanceMailFiles.filename(c.pdfTitle());int actor=access.current().userId();String hash=fingerprint(Map.of("hospital",hospital,"command",c));Long replay=replay(actor,c.requestKey(),hash);if(replay!=null)return replay;
  if(!version(hospital,c.period()).equals(c.expectedToken()))throw new BusinessException(409,"账单资料或联系人已变化，请重新打开核对");
  var attachment=artifacts.save(c.pdfTitle(),pdf.render(c.reportHtml().isBlank()?"<p></p>":c.reportHtml()));boolean[] used={false};
  try{long id=Objects.requireNonNull(tx.execute(status->{
   if(!policy(true)[1])throw new BusinessException(409,"财务邮件创建尚未开启");store.one("SELECT id FROM lin_user WHERE id=? FOR UPDATE",actor);Long previous=replay(actor,c.requestKey(),hash);if(previous!=null)return previous;
   store.one("SELECT InfoHospitalId FROM lin_lb_infohospital WHERE InfoHospitalId=? FOR UPDATE",hospital);if(!version(hospital,c.period()).equals(c.expectedToken()))throw new BusinessException(409,"账单资料或联系人已变化，请重新打开核对");
   String business=hospital+":"+Objects.toString(c.period().month(),"")+":"+Objects.toString(c.period().from(),"")+":"+Objects.toString(c.period().to(),"");
   if(Boolean.TRUE.equals(store.jdbc().queryForObject("SELECT EXISTS(SELECT 1 FROM lin_mail_message WHERE business_type='FINANCE_MAIL' AND business_id=? AND status IN ('READY','SENDING','UNKNOWN','ACCEPTED'))",Boolean.class,business)))throw new BusinessException(409,"该账单期间已有未完成投递，请先处理原记录");
   var contact=store.one("SELECT Mail FROM lin_lb_infohospitalcontact WHERE InfoHospitalId=? AND InfoHospitalContactId=? FOR SHARE",hospital,c.contactId());String mail=Objects.toString(contact.get("Mail"),"");if(mail.isEmpty()||mail.equals("0"))throw new BusinessException(400,"联系邮箱错误");var profile=store.one("SELECT UserName,BCCMail FROM lin_lb_dictmailserver WHERE DictMailServerId=? FOR SHARE",profileId);var route=LegacyMailRoutingRules.route(LegacyMailRoutingRules.Kind.FINANCE,mail,overrideTo,Objects.toString(profile.get("BCCMail"),""));String sender=Objects.toString(profile.get("UserName"),"");
   long message=store.insert("INSERT INTO lin_mail_message(business_type,business_id,requested_by,request_key,request_fingerprint,smtp_profile_id,sender_address,sender_name,recipients_json,bcc_json,subject,body_html,attachments_json,source_version,callback_json) VALUES('FINANCE_MAIL',?,?,?,?,?,?,?,?,?,?,?,?,?,?)",business,actor,c.requestKey(),hash,profileId,sender,LegacyMailAddressRules.senderName(sender),store.encode(Map.of("raw",route.to())),store.encode(Map.of("raw",route.bcc())),c.title(),c.html(),store.encode(attachment),c.expectedToken(),store.encode(Map.of("hospitalId",hospital,"period",c.period())));audit(actor,"FINANCE_MAIL_QUEUED",message,c.requestKey());used[0]=true;return message;
  }));if(!used[0])artifacts.discardUnused(attachment);return id;
  }catch(BusinessException e){artifacts.discardUnused(attachment);throw e;}
 }
 private Period period(Map<String,Object> row){var p=json(row.get("callback_json")).path("period");return new Period(p.path("month").isNull()?null:p.path("month").asText(null),p.path("from").asText(null),p.path("to").asText(null));}
 @Override protected boolean sourceUnchanged(Map<String,Object> row){long hospital=json(row.get("callback_json")).path("hospitalId").asLong();store.one("SELECT InfoHospitalId FROM lin_lb_infohospital WHERE InfoHospitalId=? FOR UPDATE",hospital);return version(hospital,period(row)).equals(row.get("source_version"));}
 @Override protected List<LegacyMailTransport.Attachment> deliveryAttachments(Map<String,Object> row){var j=json(row.get("attachments_json"));var metadata=Map.<String,Object>of("path",j.path("path").asText(),"sha256",j.path("sha256").asText());return List.of(new LegacyMailTransport.Attachment(j.path("filename").asText(),"application/pdf",artifacts.read(metadata)));}
 @Override protected void businessCallback(Map<String,Object> row){long hospital=json(row.get("callback_json")).path("hospitalId").asLong();store.one("SELECT InfoHospitalId FROM lin_lb_infohospital WHERE InfoHospitalId=? FOR UPDATE",hospital);String month=Objects.toString(period(row).month(),"");var existing=store.jdbc().queryForList("SELECT IID,IsSendMail FROM lin_lb_noticemail WHERE HospId=? AND PayMonth=? LIMIT 1 FOR UPDATE",hospital,month);var now=java.time.LocalDateTime.now(java.time.ZoneId.of("Asia/Shanghai")).withNano(0);if(existing.isEmpty())store.insert("INSERT INTO lin_lb_noticemail(HospId,PayMonth,IsSendMail,Remark,CreateDt,UpdateDt) VALUES(?,?,1,'',?,?)",hospital,month,now,now);else if(((Number)existing.get(0).get("IsSendMail")).intValue()!=1)store.jdbc().update("UPDATE lin_lb_noticemail SET IsSendMail=1,UpdateDt=? WHERE IID=?",now,existing.get(0).get("IID"));}
 public Map<String,Object> financeMessages(long hospital,Period period){read();periodDraft(hospital,period);String business=hospital+":"+Objects.toString(period.month(),"")+":"+Objects.toString(period.from(),"")+":"+Objects.toString(period.to(),"");return Map.of("items",store.jdbc().queryForList("SELECT id,status,callback_status,attempt_count,last_error_code,last_error_message,created_at FROM lin_mail_message WHERE business_type='FINANCE_MAIL' AND business_id=? ORDER BY id DESC LIMIT 50",business));}
}
